package com.example.amway; import org.junit.jupiter.api.BeforeEach; import org.junit.jupiter.api.Test; import java.util.List; import static org.junit.jupiter.api.Assertions.*; class AmwayApplicationTests { private Calculator calculator; @BeforeEach void setUp() { calculator = new Calculator(); } @Test void testCalculatorInitialValue() { assertEquals(0.0, calculator.getCurrentValue()); assertFalse(calculator.isUndoAvailable()); assertFalse(calculator.isRedoAvailable()); } @Test void testCalculatorAddition() { calculator.executeCommand(new AddCommand(10.0)); assertEquals(10.0, calculator.getCurrentValue()); calculator.executeCommand(new AddCommand(5.5)); assertEquals(15.5, calculator.getCurrentValue()); List<String> history = calculator.getHistory(); assertEquals(2, history.size()); assertEquals("0 + 10 = 10", history.get(0)); assertEquals("10 + 5.5 = 15.5", history.get(1)); } @Test void testCalculatorSubtraction() { calculator.executeCommand(new SubtractCommand(5.0)); assertEquals(-5.0, calculator.getCurrentValue()); calculator.executeCommand(new SubtractCommand(-3.0)); assertEquals(-2.0, calculator.getCurrentValue()); } @Test void testCalculatorMultiplication() { calculator.executeCommand(new AddCommand(4.0)); calculator.executeCommand(new MultiplyCommand(3.0)); assertEquals(12.0, calculator.getCurrentValue()); } @Test void testCalculatorDivision() { calculator.executeCommand(new AddCommand(10.0)); calculator.executeCommand(new DivideCommand(4.0)); assertEquals(2.5, calculator.getCurrentValue()); } @Test void testCalculatorDivisionByZero() { calculator.executeCommand(new AddCommand(10.0)); assertThrows(ArithmeticException.class, () -> { calculator.executeCommand(new DivideCommand(0.0)); }); assertEquals(10.0, calculator.getCurrentValue()); } @Test void testCalculatorUndoRedo() { calculator.executeCommand(new AddCommand(10.0)); calculator.executeCommand(new AddCommand(5.0)); calculator.executeCommand(new MultiplyCommand(2.0)); assertEquals(30.0, calculator.getCurrentValue()); assertTrue(calculator.isUndoAvailable()); assertFalse(calculator.isRedoAvailable()); double val = calculator.undo(); assertEquals(15.0, val); assertTrue(calculator.isUndoAvailable()); assertTrue(calculator.isRedoAvailable()); val = calculator.undo(); assertEquals(10.0, val); val = calculator.undo(); assertEquals(0.0, val); assertFalse(calculator.isUndoAvailable()); val = calculator.redo(); assertEquals(10.0, val); assertTrue(calculator.isUndoAvailable()); val = calculator.redo(); assertEquals(15.0, val); val = calculator.redo(); assertEquals(30.0, val); assertFalse(calculator.isRedoAvailable()); } }
